constructor(liveView, grouping = Ci.nsILiveView.UNTHREADED) {
  super();
  liveView.grouping = grouping;
  liveView.setListener(this);
  this._liveView = liveView;
}

/**
 * Extends TreeDataAdapter.setTree so that references are cleaned up when
 * the tree changes.
 *
 * @param {TreeView} tree
 */
setTree(tree) {
  if (!tree) {
    this._liveView.clearListener(this);
    this._liveView = null;
    this._rowMap.length = 0;
    this._clearFlatRowCache();
  }
  super.setTree(tree);

/**
 * Register as the one and only listener for this live view.
 */
void setListener(in nsILiveViewListener listener);

/**
 * Clean up this live view's listener, if it exists. If `listener` is passed,
 * the view's listener will not be removed if the two don't match.
 */
void clearListener([optional] in nsILiveViewListener listener);

NS_IMETHODIMP LiveView::SetListener(nsILiveViewListener* aListener) {
  bool hadListener = mListener;
  mListener = aListener;

  if (!hadListener && aListener) {
    MessageDB().AddMessageListener(this);
  }
  return NS_OK;
}

NS_IMETHODIMP LiveView::ClearListener(nsILiveViewListener* aListener) {
  if (aListener && aListener != mListener) {
    return NS_OK;
  }

  mListener = nullptr;

  MessageDB().RemoveMessageListener(this);
  return NS_OK;
